import{_ as a,c as o,o as t,ae as r}from"./chunks/framework.CliRSA9F.js";const g=JSON.parse(`{"title":"Share Your Podcast's Achievement","description":"Share your podcast's PodSEO achievement from Traction → Overview with a public profile link, one-click sharing to X, LinkedIn, WhatsApp, Threads, Bluesky and more, or a downloadable image.","frontmatter":{"description":"Share your podcast's PodSEO achievement from Traction → Overview with a public profile link, one-click sharing to X, LinkedIn, WhatsApp, Threads, Bluesky and more, or a downloadable image."},"headers":[],"relativePath":"features/share-cards.md","filePath":"features/share-cards.md"}`),i={name:"features/share-cards.md"};function n(s,e,h,l,c,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="share-your-podcast-s-achievement" tabindex="-1">Share Your Podcast&#39;s Achievement <a class="header-anchor" href="#share-your-podcast-s-achievement" aria-label="Permalink to &quot;Share Your Podcast&#39;s Achievement&quot;">​</a></h1><p>When your show qualifies, PodSEO offers a share card highlighting its visibility rank or recent score growth. Use the card to celebrate progress with listeners or include the achievement in your promotional material.</p><h2 id="open-and-share-the-card" tabindex="-1">Open and share the card <a class="header-anchor" href="#open-and-share-the-card" aria-label="Permalink to &quot;Open and share the card&quot;">​</a></h2><p>Go to <strong>Traction → Overview</strong> and click <strong>Share</strong> next to your <strong>Rank</strong>. A window titled <strong>Take a victory lap</strong> opens with a preview of your card. From there you can:</p><ul><li>Choose <strong>Copy link</strong> to share your public profile.</li><li>Share to <strong>X / Twitter</strong> or <strong>LinkedIn</strong>, or open <strong>More options</strong> for <strong>WhatsApp</strong>, <strong>Threads</strong>, <strong>Bluesky</strong>, <strong>Telegram</strong>, <strong>Reddit</strong>, <strong>Facebook</strong>, or <strong>Email</strong>. Each option opens that service&#39;s own sharing flow with a post ready for you to edit.</li><li>Click <strong>Download PNG</strong> to save the card image, or <strong>Download for Instagram</strong> for a 1080×1080 square version that also works well in X and LinkedIn posts.</li></ul><p>Review your caption before posting. A sharing shortcut opens the destination&#39;s sharing flow; it is separate from <a href="/features/social-publishing.html">Social Publishing</a>, which creates episode clips and schedules posts to connected accounts.</p><h2 id="what-the-achievement-means" tabindex="-1">What the achievement means <a class="header-anchor" href="#what-the-achievement-means" aria-label="Permalink to &quot;What the achievement means&quot;">​</a></h2><p>Cards can highlight a qualifying position in PodSEO&#39;s overall visibility ranking or positive score growth over the preceding 90 days. This is a PodSEO visibility achievement, not an Apple or Spotify chart rank and not a download or audience-size claim. See <a href="/getting-started/visibility-score-explained.html">Visibility Score Explained</a>.</p><h2 id="why-isn-t-a-card-available" tabindex="-1">Why isn&#39;t a card available? <a class="header-anchor" href="#why-isn-t-a-card-available" aria-label="Permalink to &quot;Why isn&#39;t a card available?&quot;">​</a></h2><p>Eligibility depends on the show&#39;s rank or growth, its current activity status, and having an owner tracking it in PodSEO. A paid plan alone does not guarantee a card. Competitor tracking does not give you an owner&#39;s share control for that show.</p><p>The profile is public to anyone with its link. Its availability and the achievement shown can change as the show&#39;s eligibility changes; a downloaded image remains the image you saved. Use a fresh preview when promoting a new milestone.</p>',11)])])}const u=a(i,[["render",n]]);export{g as __pageData,u as default};
